    char buf[4];
    size_t a, b, c;

    for (int i = 0; i < 10; i++)
        fputc('x', f);
    fclose(f);
    f = fopen("t.bin", "rb");
    a = fread(buf, 1, 4, f);
    b = fread(buf, 1, 4, f);
    c = fread(buf, 1, 4, f);
    printf("%zu %zu %zu\n", a, b, c);
    fclose(f);
    return 0;
}

